    else if (t === 'rule_id') ok = lc(a.rule_id) === v;
    else if (t === 'field' && w.field) { try { ok = new RegExp(String(w.value), 'i').test(String(a[w.field] === undefined ? '' : a[w.field])); } catch (e) { ok = false; } }
