};
const recent = {};
for (const i of $input.all()) { const r = i.json; if (r && r.fingerprint) recent[r.fingerprint] = r; }
const test = (r, a) => {
  if (r.rule_id && String(r.rule_id).split(',').map((x) => x.trim()).indexOf(a.rule_id) < 0) return false;
  if (r.agent && String(r.agent).toLowerCase() !== String(a.agent).toLowerCase()) return false;
  if (r.field && r.pattern) { try { return new RegExp(r.pattern, 'i').test(String(a[r.field] === undefined ? '' : a[r.field])); } catch (e) { return false; } }
  return !!(r.rule_id || r.agent);
};
const groups = {};
for (const a of alerts) {
  const g = groups[a.fingerprint];
  if (g) {
    g.batch += 1; if (a.ts > g.last) g.last = a.ts; if (a.ts < g.first) g.first = a.ts;
    for (const k of ['cves', 'detection_ids', 'detection_names']) g[k] = Array.from(new Set((g[k] || []).concat(a[k] || [])));
  }
  else groups[a.fingerprint] = Object.assign({}, a, { batch: 1, first: a.ts, last: a.ts });
