const out = [];
const cand = [];
for (const a of Object.values(groups)) {
  const prev = recent[a.fingerprint];
  a.prev_count = prev ? Number(prev.count || 0) : 0;
  a.prev_verdict = prev ? (prev.verdict || '') : '';
  a.first_seen = prev && prev.first_seen ? prev.first_seen : a.first;
  a.notified = prev ? prev.notified === true : false;
  a.fp_percent = prev && prev.fp_percent !== undefined ? prev.fp_percent : null;
  a.summary = prev ? (prev.summary || '') : '';
  a.intel = prev ? (prev.intel || '') : '';
  a.suppress_hint = prev ? (prev.suppress_hint || '') : '';
  const wh = watchHits(a);
  if (wh.length) {
    a.watch = wh;
    const recentWatch = prev && prev.notified === true && prev.last_seen && (now - new Date(prev.last_seen).getTime()) < WATCH_REPEAT_MIN * 60000;
