  const age = prev && prev.last_seen ? (now - new Date(prev.last_seen).getTime()) / 3600000 : 1e9;
  const win = prev && prev.verdict === 'noise' ? NOISE_HOURS : DEDUP_HOURS;
  if (!force && prev && age < win && ['escalate', 'monitor', 'noise', 'burst', 'untriaged'].indexOf(prev.verdict) >= 0) {
